test('trickle sends the offer immediately and delivers candidates gathered afterward',async()=>{
 const pc=new Peer(),timers=new Timers(),signals=[],batches=[];pc.iceGatheringState='gathering';
 const client=transport.createOnlinePeer({role:'host',room:'ABC123',peer:pc,timers,sendSignal:value=>signals.push(value),sendCandidates:value=>batches.push(value)});
 try{const started=client.start();await flushTasks();assert.equal(signals.length,1);await started;assert.equal(signals[0].generation,1);
 pc.emit('icecandidate',{candidate:{toJSON:()=>({candidate:'candidate:late typ srflx',sdpMid:'0',sdpMLineIndex:0,usernameFragment:null})}});timers.advance(100);await flushTasks();assert.equal(batches.length,1);assert.equal(batches[0].generation,1);
 }finally{client.close();}
});
test('remote ICE candidates wait for their matching SDP and are applied only once',async()=>{
 const pc=new Peer(),timers=new Timers(),added=[];pc.addIceCandidate=async value=>{assert.ok(pc.remoteDescription);added.push(value);};
 const client=transport.createOnlinePeer({role:'guest',room:'ABC123',peer:pc,timers,sendSignal:()=>{}}),candidate={candidate:'candidate:early typ host',sdpMid:'0',sdpMLineIndex:0,usernameFragment:null};
 try{await client.receiveCandidates({generation:1,candidates:[candidate,candidate]});assert.deepEqual(added,[]);
 await client.receiveDescription({type:'offer',sdp:'v=0 host',generation:1});assert.equal(added.length,1);
 await client.receiveCandidates({generation:1,candidates:[candidate]});assert.equal(added.length,1);
 await client.receiveDescription({type:'offer',sdp:'v=0 restart',generation:2});
 await client.receiveCandidates({generation:1,candidates:[candidate]});assert.equal(added.length,1);
 }finally{client.close();}
});
test('host makes one ICE restart with a fresh negotiation deadline before giving up',async()=>{
 const pc=new Peer(),timers=new Timers(),signals=[],offers=[],ended=[];pc.createOffer=async options=>{offers.push(options);return {type:'offer',sdp:'v=0 host '+offers.length};};
 const client=transport.createOnlinePeer({role:'host',room:'ABC123',peer:pc,timers,sendSignal:value=>signals.push(value),onDisconnect:value=>ended.push(value)});
 try{await client.start();pc.connectionState='failed';pc.emit('connectionstatechange');await flushTasks();assert.equal(offers.length,2);assert.equal(offers[1].iceRestart,true);assert.equal(signals[1].generation,2);assert.deepEqual(ended,[]);
 timers.advance(17000);assert.deepEqual(ended,[]);timers.advance(2000);await flushTasks();assert.equal(offers.length,2);assert.equal(ended.length,1);
 }finally{client.close();}
});
test('host authority waits for the guest start acknowledgement and rejects old-match acknowledgements',()=>{
 const sent=[],frames=[],session=lobby.createOnlineSession({seat:{role:'host'},peer:{setMatchId(){},send:p=>sent.push(p)},postFrame:p=>frames.push(p),loadFrame(){}});
 session.connected();session.receiveFrame({type:'loaded'});session.receivePeer({type:'loaded'});assert.ok(sent.some(p=>p.type==='start'));assert.equal(frames.some(p=>p.type==='start'),false);
 session.receivePeer({type:'started',matchId:2});assert.equal(frames.some(p=>p.type==='start'),false);
 session.receivePeer({type:'started',matchId:1});assert.equal(frames.filter(p=>p.type==='start').length,1);
 session.receivePeer({type:'started',matchId:1});assert.equal(frames.filter(p=>p.type==='start').length,1);session.end('Done');
});

test('new connection and station cohort refuses the previous cached wire build',()=>{const p=peerPair({guestVersion:'system-clash-20261009-7'});try{p.open();assert.equal(p.host.connected,false);assert.ok(p.disconnected.flat().some(reason=>/versions differ/.test(reason)));}finally{p.host.close();p.guest.close();}});
test('disposing a pending start clears the handshake timeout and never ends a newer session',()=>{
 const timers=new Timers(),ended=[],frames=[],session=lobby.createOnlineSession({seat:{role:'host'},peer:{setMatchId(){},send(){}},timers,postFrame:p=>frames.push(p),onEnd:r=>ended.push(r)});
 session.connected();session.receiveFrame({type:'loaded'});session.receivePeer({type:'loaded'});assert.ok(timers.jobs.size);session.destroy();timers.advance(9000);assert.deepEqual(ended,[]);assert.equal(timers.jobs.size,0);assert.equal(frames.some(p=>p.type==='start'),false);
});
