test('guest lobby waits for the initialized fight frame before acknowledging host and forwarding neutral input',()=>{
 const sent=[],frames=[],session=lobby.createOnlineSession({seat:{role:'guest'},peer:{setMatchId(){},send:packet=>sent.push(packet)},postFrame:packet=>frames.push(packet),loadFrame(){}});
 session.connected();session.receivePeer({type:'setup'});session.receiveFrame({type:'loaded'});session.receivePeer({type:'start',matchId:1,seed:77});
 assert.equal(frames.filter(packet=>packet.type==='start').length,1);assert.equal(sent.some(packet=>packet.type==='started'),false);
 const neutral={type:'input',input:{move:0,crouch:false,block:false}};session.receiveFrame(neutral);assert.equal(sent.some(packet=>packet.type==='input'),false);
 session.receiveFrame({type:'started',matchId:2});assert.equal(sent.some(packet=>packet.type==='started'),false);
 session.receiveFrame({type:'started',matchId:1});session.receiveFrame(neutral);assert.deepEqual(sent.slice(-2),[{type:'started',matchId:1},neutral]);
 session.receiveFrame({type:'started',matchId:1});assert.equal(sent.filter(packet=>packet.type==='started').length,1);session.destroy();
});

test('initial private room state gates Ready and fighter selection for create and join latency',async()=>{
 for(const action of ['create','join']){
  let release;const waiting=new Promise(resolve=>release=resolve),state={host:{name:'A',fighter:'6-bit',ready:false},guest:action==='join'?{name:'B',fighter:'9-bit',ready:false}:null};
  const f=await mountedLobby({pollWait:waiting,pollStates:[state]});
  try{
   if(action==='create')f.elements.get('create-room').click();else{f.elements.get('join-code').value='ABC123';f.elements.get('join-form').emit('submit',{preventDefault(){}});}
   await flushTasks();assert.equal(f.elements.get('room-panel').hidden,false);assert.equal(f.elements.get('ready-button').disabled,true);assert.match(f.elements.get('ready-button').textContent,/loading/i);assert.ok(f.elements.get('fighter-grid').children.every(button=>button.disabled));assert.equal(f.elements.get('stage-choice').disabled,true);
   f.elements.get('ready-button').click();f.elements.get('fighter-grid').children.find(button=>button.dataset.fighter==='9-bit').click();await flushTasks();assert.equal(f.requests.filter(request=>request.body?.action==='select').length,0);
   release();await flushTasks();assert.equal(f.elements.get('ready-button').disabled,false);assert.equal(f.elements.get('fighter-grid').children.find(button=>button.dataset.fighter==='9-bit').disabled,false);assert.equal(f.elements.get('stage-choice').disabled,action==='join');
   f.elements.get('ready-button').click();await flushTasks();assert.equal(f.requests.filter(request=>request.body?.action==='select').length,1);assert.equal(f.elements.get('ready-button').attributes['aria-pressed'],'true');
  }finally{release();f.mounted.destroy();}
 }
});
test('initial poll failure keeps selection gated and its scheduled retry enables valid state',async()=>{
 let polls=0;const f=await mountedLobby({pollWait:()=>{if(++polls===1)throw Error('Temporary poll failure');},pollStates:[{host:{name:'A',fighter:'6-bit',ready:false},guest:null}]});
 try{f.elements.get('create-room').click();await flushTasks();assert.equal(f.elements.get('ready-button').disabled,true);assert.ok(f.elements.get('fighter-grid').children.every(button=>button.disabled));assert.equal(f.elements.get('leave-room').disabled,false);f.timers.advance(1500);await flushTasks();assert.equal(polls,2);assert.equal(f.elements.get('ready-button').disabled,false);assert.equal(f.elements.get('selected-fighter').textContent,'6 Bit');assert.equal(f.peers.length,0);}finally{f.mounted.destroy();}
});
test('leaving during initial private polling releases the seat and stale response cannot reopen it',async()=>{
 let release;const waiting=new Promise(resolve=>release=resolve);const f=await mountedLobby({pollWait:waiting});
 try{f.elements.get('create-room').click();await flushTasks();assert.equal(f.elements.get('ready-button').disabled,true);f.elements.get('leave-room').click();await flushTasks();assert.equal(f.elements.get('room-panel').hidden,true);assert.ok(f.requests.some(request=>request.body?.action==='leave'));release();await flushTasks();assert.equal(f.elements.get('room-panel').hidden,true);assert.equal(f.peers.length,0);assert.equal(f.requests.filter(request=>request.body?.action==='select').length,0);}finally{release();f.mounted.destroy();}
});
test('stopping after poll failures clears a pending selection so Leave remains usable',async()=>{
 let release,polls=0;const waiting=new Promise(resolve=>release=resolve);const f=await mountedLobby({selectWait:waiting,pollWait:()=>{if(++polls>1)throw Error('Session unavailable');},pollStates:[{host:{name:'A',fighter:'6-bit',ready:false},guest:null}]});
 try{f.elements.get('create-room').click();await flushTasks();f.elements.get('fighter-grid').children.find(button=>button.dataset.fighter==='9-bit').click();await flushTasks();for(let i=0;i<3;i++){f.timers.advance(1500);await flushTasks();}assert.equal(f.elements.get('ready-button').textContent,'Connection ended');f.elements.get('leave-room').click();await flushTasks();assert.equal(f.elements.get('room-panel').hidden,true);release();await flushTasks();assert.equal(f.elements.get('room-panel').hidden,true);}finally{release();f.mounted.destroy();}
});

test('network pause reasons and cross-lane input sequence numbers are bounded before routing',()=>{
 for(const type of ['input','action']){
  const base={type,input,...(type==='action'?{action:'punch'}:{})};
  assert.equal(protocol.validPayload({...base,inputSeq:1}),true);
  for(const inputSeq of [0,-1,1.5,'1',Infinity,4294967296,Number.MAX_SAFE_INTEGER+1])assert.equal(protocol.validPayload({...base,inputSeq}),false);
 }
 assert.equal(protocol.validPayload({type:'pause',paused:true,reason:'network'}),true);
 assert.equal(protocol.validPayload({type:'pause',paused:true,reason:'manual'}),true);
 for(const reason of ['admin','',false,{}])assert.equal(protocol.validPayload({type:'pause',paused:true,reason}),false);
 for(const snapshotSeq of [-1,'3',Infinity,1.2])assert.equal(protocol.validPayload({type:'pause',paused:false,snapshotSeq}),false);
});
test('a transient network stall is shown separately from a deliberate player pause',()=>{
 const statuses=[],sent=[];
 const session=lobby.createOnlineSession({seat:{role:'host'},roomState:{},peer:{setMatchId(){},send:p=>sent.push(p)},onStatus:s=>statuses.push(s),timers:new Timers()});
 session.connected();session.receiveFrame({type:'loaded'});session.receivePeer({type:'loaded'});session.receivePeer({type:'started',matchId:1});
 session.receiveFrame({type:'pause',paused:true,reason:'network'});
 assert.match(statuses.at(-1),/connection|network/i);
 assert.doesNotMatch(statuses.at(-1),/by a player/i);
 session.receiveFrame({type:'pause',paused:false,reason:'network',snapshotSeq:0});assert.equal(statuses.at(-1),'Clash!');
 session.receiveFrame({type:'pause',paused:true,reason:'manual'});assert.equal(statuses.at(-1),'Paused by a player.');
 session.destroy();
});

test('ready seats receive short-lived real-time relay configuration before creating the peer',async()=>{
 const iceConfig={iceServers:[{urls:['turns:turn.cloudflare.com:443?transport=tcp'],username:'short-user',credential:'short-pass'}],realtimeRelay:true};
 const f=await mountedLobby({iceConfig});try{
  f.elements.get('create-room').click();await flushTasks();
  assert.equal(f.requests.filter(r=>r.body?.action==='ice').length,1);assert.equal(f.peers.length,1);
  assert.ok(f.peers[0].configuration.iceServers.some(s=>s.username==='short-user'&&s.credential==='short-pass'));
  assert.equal(f.requests.find(r=>r.body?.action==='ice').options.headers.Authorization,'Bearer private-seat');
  f.timers.advance(1500);await flushTasks();assert.equal(f.requests.filter(r=>r.body?.action==='ice').length,1);
 }finally{f.mounted.destroy();}
});
test('leaving during connection preparation cannot create a late peer or retain credentials',async()=>{
 let release;const wait=new Promise(resolve=>release=resolve),f=await mountedLobby({iceWait:wait});
 try{f.elements.get('create-room').click();await flushTasks();assert.equal(f.peers.length,0);assert.equal(f.elements.get('leave-room').disabled,false);
  f.elements.get('leave-room').click();await flushTasks();release();await flushTasks();
  assert.equal(f.peers.length,0);assert.equal(f.elements.get('room-panel').hidden,true);
 }finally{release();f.mounted.destroy();}
});
test('real-time credential service failure retains direct STUN and the existing bounded fallback',async()=>{
 const f=await mountedLobby({iceError:true});try{f.elements.get('create-room').click();await flushTasks();assert.equal(f.requests.filter(r=>r.body?.action==='ice').length,1);assert.equal(f.peers.length,1);
  assert.ok(f.peers[0].configuration.iceServers.length>0);assert.ok(f.peers[0].configuration.iceServers.every(s=>!s.credential));
 }finally{f.mounted.destroy();}
});


test('malformed realtime credentials cannot install arbitrary servers or interrupt lobby fallback',async()=>{
 for(const iceServers of [[{urls:['turns:untrusted.test:443?transport=tcp'],username:'x',credential:'y'}],[{urls:['turns:turn.cloudflare.com:443?transport=tcp'],username:'x',credential:{}}],Array.from({length:9},()=>({urls:['turns:turn.cloudflare.com:443?transport=tcp'],username:'x',credential:'y'}))]){
  const f=await mountedLobby({iceConfig:{iceServers,realtimeRelay:true}});try{f.elements.get('create-room').click();await flushTasks();assert.equal(f.peers.length,1);assert.ok(f.peers[0].configuration.iceServers.length>0);assert.ok(f.peers[0].configuration.iceServers.every(s=>!s.credential));}finally{f.mounted.destroy();}
 }
});
